import { useMemo } from 'react';

import { useLastDataRefresh } from 'contexts';
import { Period } from 'domain/Period';

export interface PowerBookPeriods {
  qtdPeriod: string;
  ytdPeriod: string;
  qtdCoverPrefix: string;
  qtdCoverYear: string;
  fiscalYear: string;
  quarterYearFull: string;
}

export const usePowerBookPeriods = (): PowerBookPeriods => {
  const { lastDataRefreshKpisDate } = useLastDataRefresh();

  return useMemo(() => {
    const power = lastDataRefreshKpisDate.power;

    if (!power) {
      return {
        qtdPeriod: '',
        ytdPeriod: '',
        qtdCoverPrefix: '',
        qtdCoverYear: '',
        fiscalYear: '',
        quarterYearFull: '',
      };
    }

    const qtd = Period.from(power);
    const ytd = Period.from(power, 'YTD');

    return {
      qtdPeriod: qtd.slideLabel,
      ytdPeriod: ytd.slideLabel,
      qtdCoverPrefix: qtd.coverPrefix,
      qtdCoverYear: qtd.coverYear,
      fiscalYear: ytd.coverYear,
      quarterYearFull: qtd.coverFallback,
    };
  }, [lastDataRefreshKpisDate.power]);
};
